toolArgs.file_text:
/* Chat Layout */
::deep .chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

::deep .sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #202225;
}

::deep .sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #8e9297;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #36393f;
}

::deep .channel-item.active {
    background: #393c43;
    color: #fff;
}

::deep .channel-item-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

::deep .unread-badge {
    background: #ed4245;
    color: #fff;
    border-radius: 10px;
    padding: 1px 6px;
    font-size: 0.75rem;
    font-weight: 700;
}

::deep .channel-description {
    font-size: 0.8rem;
    color: #72767d;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Main Message Area */
::deep .chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

::deep .chat-main.with-thread {
    flex: 0 0 55%;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    background: #36393f;
    color: #dcddde;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 12px;
    color: #8e9297;
    font-size: 0.85rem;
}

/* Message Bubble */
::deep .message-bubble {
    position: relative;
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #72767d;
}

::deep .message-content {
    font-size: 0.95rem;
    line-height: 1.4;
    word-wrap: break-word;
}

::deep .message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

::deep .reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #4f545c;
}

::deep .thread-link {
    margin-top: 6px;
    font-size: 0.85rem;
    color: #00aff4;
    cursor: pointer;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
}

::deep .action-btn {
    background: transparent;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    font-size: 0.8rem;
    padding: 4px 8px;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #4f545c;
    color: #fff;
}

::deep .emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 6px 8px;
    z-index: 10;
}

::deep .emoji-option {
    cursor: pointer;
    font-size: 1.2rem;
    padding: 2px 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .emoji-option:hover {
    background: #4f545c;
}

/* Message Input */
::deep .message-input-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #202225;
    background: #36393f;
}

::deep .message-textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    padding: 10px 14px;
    color: #dcddde;
    font-size: 0.95rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-textarea::placeholder {
    color: #72767d;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 10px 18px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .close-btn {
    background: transparent;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #4f545c;
